  ocr_batch_strategy: batch.ocr_batch_strategy, text, modelVersion: 'tesseract-5.5.0',
  responseId: null, ocr_fallback_reason: batch.ocr_fallback_reason || 'OCR_BATCH_RATE_LIMIT'
}, pairedItem: { item: 0 }}];

let rawError = $json?.error || $json?.errorMessage || $json?.message || 'legal ingestion failed';
if (typeof rawError === 'object' && rawError !== null) {
  rawError = rawError.message || JSON.stringify(rawError);
}
const errMsg = String(rawError || 'legal ingestion failed').slice(0, 500);

let reserveJson = {};
try {
  reserveJson = $('Reserve Legal Source').first()?.json || {};
} catch (e) {}

const runId = $json?.run_id || reserveJson.run_id || null;
const docId = $json?.document_id || reserveJson.document_id || null;
const fileId = $json?.file_id || reserveJson.file_id || null;
const fileName = $json?.file_name || reserveJson.file_name || null;
const errCode = $json?.error_code || $json?.error?.name || 'INGESTION_FAILED';

return [{
  json: {
    run_id: runId,
    document_id: docId,
    file_id: fileId,
    file_name: fileName,
    error_code: String(errCode).slice(0, 100),
    error_message: errMsg
  }
}];

// Reset all static state between files
const staticData = $getWorkflowStaticData('global');
delete staticData.gemini_quota_exhausted;
delete staticData.current_file_batches;

// Allow Node.js GC to clean memory from previous file
await new Promise(resolve => setTimeout(resolve, 1000));

// Return clean, lightweight payload with zero residual binary or bloated JSON
return [{
  json: {
    file_reset_clean: true,
    timestamp: Date.now()
  }
}];
